-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Pool.json. Do not edit: change the chain file or ABI and regenerate.
-- Collect(address,address,int24,int24,uint128,uint128)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_pool__collect',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as owner,
    concat('0x', substring(substring(data, 3, 64), 25, 40)) as recipient,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic2, 3, 64))))) as tick_lower,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic3, 3, 64))))) as tick_upper,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64))))) as amount0,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64))))) as amount1
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0x70935338e69775456a85ddef226c395fb668b63fa0115f5f20610b388e6ca9c0'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
